def is_between(i,j,inp):
    h,w=len(inp),len(inp[0])
    R=[k for k in range(j+1,w) if inp[i][k]==2]
    L=[k for k in range(j) if inp[i][k]==2]
    D=[k for k in range(i+1,h) if inp[k][j]==2]
    U=[k for k in range(i) if inp[k][j]==2]
    return (R and L) or (D and U)
