from collections import deque
def f(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    # iterative: 3-cells adjacent to known-passable become passable
    changed=True
    while changed:
        changed=False
        for i in range(h):
            for j in range(w):
                if g[i][j]==3 and not seen[i][j]:
                    nb=[(a,b) for a in range(max(0,i-1),min(h,i+2)) for b in range(max(0,j-1),min(w,j+2))]
                    if any(seen[a][b] for a,b in nb if (a,b)!=(i,j)):
                        seen[i][j]=True; changed=True
    return [[1 if g[i][j]==3 and not seen[i][j] else g[i][j] for j in range(w)] for i in range(h)]
for name in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    inp=G[name+' input']; out=G[name+' output']
